import math


def dew_point(t_c: float, rh: float) -> float:
    if rh <= 0.0 or rh > 100.0:
        raise ValueError("rh must be in the range (0, 100]")

    a = 17.62
    b = 243.12

    if rh == 100.0:
        return float(t_c)

    gamma = math.log(rh / 100.0) + a * (t_c / (b + t_c))
    return b * gamma / (a - gamma)

_ROMAN_VALUES = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
]

_CHAR_VALUES = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}


def int_to_roman(n: int) -> str:
    if not isinstance(n, int):
        raise ValueError("n must be an integer in the range 1..3999")
    if n < 1 or n > 3999:
        raise ValueError("n must be in the range 1..3999")

    parts = []
    remaining = n

    for value, numeral in _ROMAN_VALUES:
        count = remaining // value
        if count:
            parts.extend([numeral] * count)
            remaining -= value * count

    return "".join(parts)


def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("s must be a Roman numeral string")
    if not s:
        raise ValueError("s must not be empty")
    if any(char not in _CHAR_VALUES for char in s):
        raise ValueError("s contains invalid Roman numeral characters")

    values = [_CHAR_VALUES[char] for char in s]
    total = 0

    for i, value in enumerate(values):
        if i + 1 < len(values) and value < values[i + 1]:
            total -= value
        else:
            total += value

    if total < 1 or total > 3999:
        raise ValueError("s is not a Roman numeral in the range 1..3999")

    if s != int_to_roman(total):
        raise ValueError("s is not a canonical Roman numeral")

    return total

def merge_intervals(iv: list[tuple[float, float]]) -> list[tuple[float, float]]:
    for start, end in iv:
        if start > end:
            raise ValueError("start must not be greater than end")

    merged: list[tuple[float, float]] = []

    for start, end in sorted(iv, key=lambda interval: (interval[0], interval[1])):
        if merged and start <= merged[-1][1]:
            prev_start, prev_end = merged[-1]
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return merged

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._cache = OrderedDict()

    def get(self, key):
        if key not in self._cache:
            return -1
        self._cache.move_to_end(key)
        return self._cache[key]

    def put(self, key, value) -> None:
        if key in self._cache:
            self._cache.move_to_end(key)
        elif len(self._cache) >= self.capacity:
            self._cache.popitem(last=False)
        self._cache[key] = value

import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for prerequisites in deps.values():
        nodes.update(prerequisites)

    indegree = {node: 0 for node in nodes}
    outgoing = {node: [] for node in nodes}

    for node, prerequisites in deps.items():
        for prerequisite in set(prerequisites):
            indegree[node] += 1
            outgoing[prerequisite].append(node)

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)

    result: list[str] = []

    while available:
        node = heapq.heappop(available)
        result.append(node)

        for successor in outgoing[node]:
            indegree[successor] -= 1
            if indegree[successor] == 0:
                heapq.heappush(available, successor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF

    for byte in data:
        crc ^= byte << 8

        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF

    return crc

def sliding_median(values: list[float], k: int) -> list[float]:
    if k < 1 or k > len(values):
        raise ValueError("k must satisfy 1 <= k <= len(values)")

    n = len(values)
    unique = sorted(set(values))
    m = len(unique)

    index_of = {v: i + 1 for i, v in enumerate(unique)}
    compressed = [index_of[v] for v in values]

    tree = [0] * (m + 1)
    highest_power = 1 << (m.bit_length() - 1)

    def add(pos: int, delta: int) -> None:
        while pos <= m:
            tree[pos] += delta
            pos += pos & -pos

    def kth(order: int) -> int:
        idx = 0
        step = highest_power
        while step:
            nxt = idx + step
            if nxt <= m and tree[nxt] < order:
                idx = nxt
                order -= tree[nxt]
            step >>= 1
        return idx + 1

    for i in range(k):
        add(compressed[i], 1)

    result: list[float] = []
    append = result.append

    if k & 1:
        target = k // 2 + 1
        for start in range(n - k + 1):
            if start:
                add(compressed[start - 1], -1)
                add(compressed[start + k - 1], 1)
            append(float(unique[kth(target) - 1]))
    else:
        lower = k // 2
        upper = lower + 1
        for start in range(n - k + 1):
            if start:
                add(compressed[start - 1], -1)
                add(compressed[start + k - 1], 1)
            a = unique[kth(lower) - 1]
            b = unique[kth(upper) - 1]
            append(float(a) / 2.0 + float(b) / 2.0)

    return result

class RunningStats:
    """Laufende statistische Kennzahlen nach Welford (numerisch stabil)."""

    def __init__(self) -> None:
        self._count: int = 0
        self._mean: float = 0.0
        self._m2: float = 0.0

    def add(self, x: float) -> None:
        """Fügt einen neuen Wert zur Statistik hinzu."""
        x = float(x)
        self._count += 1
        delta = x - self._mean
        self._mean += delta / self._count
        delta2 = x - self._mean
        self._m2 += delta * delta2

    @property
    def count(self) -> int:
        """Anzahl der hinzugefügten Werte."""
        return self._count

    @property
    def mean(self) -> float:
        """Durchschnittswert; bei count == 0 liefert 0.0."""
        if self._count == 0:
            return 0.0
        return self._mean

    @property
    def variance(self) -> float:
        """Stichprobenvarianz (n-1); bei count < 2 liefert 0.0."""
        if self._count < 2:
            return 0.0
        variance = self._m2 / (self._count - 1)
        return variance if variance > 0.0 else 0.0

    @property
    def std(self) -> float:
        """Standardabweichung (Stichprobe); bei count < 2 liefert 0.0."""
        return self.variance ** 0.5

from math import exp


def rh_after_mixing(
    t1: float,
    rh1: float,
    m1: float,
    t2: float,
    rh2: float,
    m2: float,
    p: float = 101325.0
) -> tuple[float, float]:
    if m1 <= 0 or m2 <= 0:
        raise ValueError("Die Trockenluft-Massenstroeme muessen groesser als 0 sein.")

    def saturation_vapor_pressure(t_c: float) -> float:
        return 611.2 * exp(17.62 * t_c / (243.12 + t_c))

    def humidity_ratio(t_c: float, rh_percent: float, pressure: float) -> float:
        e_s = saturation_vapor_pressure(t_c)
        e = (rh_percent / 100.0) * e_s
        return 0.622 * e / (pressure - e)

    m_total = m1 + m2

    t_mix = (m1 * t1 + m2 * t2) / m_total

    x1 = humidity_ratio(t1, rh1, p)
    x2 = humidity_ratio(t2, rh2, p)
    x_mix = (m1 * x1 + m2 * x2) / m_total

    e_mix = x_mix * p / (0.622 + x_mix)
    rh_mix = 100.0 * e_mix / saturation_vapor_pressure(t_mix)

    return float(t_mix), float(rh_mix)
